mapper.select:
select
concat_ws(' - ', Min(`card_number`), MAX(`card_number`))  as `numberSegment`,
    `org_id`                                              as `allocateOrgId`
from `card`
where `coupon_id` = #{couponId}
  and `coupon_allocate_id` in

        #{item}

group by `coupon_allocate_id`
order by `card_number` asc;

select
    `card_number`,
    `card_password`,
    `org_id`
from `card`
where `coupon_id` = #{couponId}
and `coupon_allocate_id` in

    #{item}

order by `card_number` asc;

select `id`, `card_number`, `card_password`, `sold_target`, `sold_phone_number`, `sold_type`, `link`, `status`, `is_pay`, `sold_way` from `card` where `coupon_id` = #{couponId} and `org_id` = #{orgId}
and `card_number` like concat('%', #{cardNumber}, '%')
and `sold_phone_number` like concat('%', #{phoneNumber}, '%')
and `sold_type` in
#{item}
and `status` in
#{item}
order by `status` asc, `id` asc

select
    count(`id`) - sum(`status` in (1, 2))
from `card`
where `coupon_id` = #{couponId}
  and `org_id` = #{orgId}
group by `coupon_id`, `org_id`;

select `c`.`id` as `cardId`, `cci`.`id` as `couponId`, `cci`.`name` as `couponName`, `c`.`card_number`, `cci`.`type` as `couponType`, `cci`.`product_type_id`, `c`.`sale_channel_id`, case when `cci`.`type` = 2 then (select `use_way` from `package_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 2 then (select `use_way` from `special_package_coupon` where `coupon_id` = `c`.`coupon_id`) else null end as `useWay`, case when `cci`.`type` = 0 then (select date_format(date_add(`c`.`active_date`, interval `effective_days` day), '%Y-%m-%d') from `vouche_coupon` where `coupon_id` = `c`.coupon_id) when `cci`.`type` = 1 then (select date_add(`c`.`active_date`, interval `effective_days` day) from `discount_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 2 then (select date_add(`c`.`active_date`, interval `effective_days` day) from `package_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 3 then (select date_add(`c`.`active_date`, interval `effective_days` day) from `special_package_coupon` where `coupon_id` = `c`.`coupon_id`) else null end as `useDeadline`, date_format(`c`.`active_date`, '%Y-%m-%d') as `activeDate`, case when `cci`.`type` = 0 then (select `is_share` from `vouche_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 1 then (select `is_share` from `discount_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 2 then (select `is_share` from `package_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 3 then (select `is_share` from `special_package_coupon` where `coupon_id` = `c`.`coupon_id`) else null end as `share`
, `c`.`patient_id` as `cardOwner`
from `card` `c` inner join `coupon_common_info` `cci` on `c`.`coupon_id` = `cci`.`id` where
`c`.`patient_id` = #{patientId}
find_in_set(#{patientId}, `c`.`sharer`) and `c`.`patient_id` != #{patientId}
and `cci`.`name` like concat('%', #{couponName}, '%')
and `cci`.`type` in
#{item}
